output:
```python
def soma_pares(numbers):
    return sum(num for num in numbers if num % 2 == 0)
```

```python
def soma_pares(lst):
    return sum(num for num in lst if num % 2 == 0)

print(soma_pares([1, 2, 3, 4]))  # 6
```

```java
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] numbers = new int[5]; // Assuming the list has 5 elements
        int sum = 0;

        System.out.println("Digite 5 números inteiros:");
        for (int i = 0; i < numbers.length; i++) {
            numbers[i] = scanner.nextInt();
        }

        for (int number : numbers) {
            if (number % 2 == 0) {
                sum += number;
            }
        }

        System.out.println("A soma dos números pares é: " + sum);
    }
}
```

```java
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] lista = new int[0];
        int soma = 0;

        while (true) {
            System.out.print("Digite um numero (ou 'fim' para parar): ");
            String input = scanner.nextLine();

            if (input.equalsIgnoreCase("fim")) {
                break;
            }

            try {
                int numero = Integer.parseInt(input);
                if (numero < 0) {
                    System.out.println("Não é possível calcular a soma de números negativos.");
                } else {
                    lista = new int[lista.length + 1];
                    lista[0] = numero;
                    for (int i = 1; i < lista.length; i++) {
                        lista[i] = lista[i - 1] + numero;
                    }
                    soma = lista[lista.length - 1];
                    System.out.println("Soma dos números pares: " + soma);
                }
            } catch (NumberFormatException e) {
                System.out.println("Não é possível calcular a soma de números negativos.");
            }
        }

        scanner.close();
    }
}
```

```java
import java.util.List;

class Solution {
    public int sumOfEvenNumbers(List<Integer> numbers) {
        int sum = 0;
        for (int number : numbers) {
            if (number % 2 == 0) {
                sum += number;
            }
        }
        return sum;
    }
}
```

